#include <errno.h>
#include <stddef.h>
#include <stdint.h>

/* This application never allocates heap. Expose attempted growth as a
 * measured counter rather than treating a linker reserve as usage. */
volatile uint32_t heap_attempts;
void *_sbrk(ptrdiff_t incr) {
  (void)incr;
  ++heap_attempts;
  errno = ENOMEM;
  return (void *)-1;
}
